import{_ as o,o as t,c as s,ag as c}from"./chunks/framework.DLWhSH9p.js";const p=JSON.parse('{"title":"CLAUDE.md","description":"","frontmatter":{},"headers":[],"relativePath":"CLAUDE.md","filePath":"CLAUDE.md"}'),d={name:"CLAUDE.md"};function r(i,e,a,n,l,h){return t(),s("div",null,[...e[0]||(e[0]=[c('<h1 id="claude-md" tabindex="-1">CLAUDE.md <a class="header-anchor" href="#claude-md" aria-label="Permalink to &quot;CLAUDE.md&quot;">​</a></h1><p>This file provides guidance to Claude Code (claude.ai/code) when working with code in this repository.</p><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p><code>docs</code> is the <strong>VitePress user guide</strong> for CRAFT Studio and the creator marketplace, deployed to <strong>docs.mossworks.io</strong> (GitHub Pages). It is audience-facing <strong>end-user</strong> documentation, distinct from the per-repo developer docs (<code>CLAUDE.md</code> / <code>README.md</code>) elsewhere in the Mossworks workspace.</p><p><code>package.json</code> name is <code>craft-docs</code>. Guide pages live under <code>guide/</code> (one <code>.md</code> per topic), the landing page is <code>index.md</code>, and the VitePress site title is &quot;CRAFT Studio&quot; (Content Refinement &amp; Authoring Framework Toolkit).</p><p>The repo is <strong>more than a VitePress site</strong> — it also carries a <strong>Playwright capture subsystem</strong> with two distinct workloads that boot the live apps:</p><ul><li><strong><code>screenshots</code></strong> — auto-captures the guide PNGs in <strong>7 colour schemes</strong> (amber, blue, liquidgold, otter, purple, rose, xanderu) into <code>public/screenshots/</code>. Auths via Keycloak ROPC against the <code>mobile</code> client (programmatic; runs in CI-style flows). Viewport 1440×900.</li><li><strong><code>tour</code></strong> — records a 1080p <code>.webm</code> walkthrough of the headline studio workflow (for the marketing site, not the guide). Auths via an interactive sign-in whose <code>storageState</code> is captured once with <code>npm run tour:auth</code>. Viewport 1920×1080, video on.</li></ul><p>The README documents the VitePress side and the <code>&lt;SchemeImage&gt;</code> / <code>&lt;FlatImage&gt;</code> authoring API but deliberately punts on the capture pipeline (&quot;operator-internal&quot;); this file fills that gap.</p><h2 id="build-commands" tabindex="-1">Build Commands <a class="header-anchor" href="#build-commands" aria-label="Permalink to &quot;Build Commands&quot;">​</a></h2><p>From <code>package.json</code> scripts:</p><ul><li><code>npm run dev</code> — VitePress dev server. The script passes <code>--host 0.0.0.0</code> (binds all interfaces); the URL is <code>http://localhost:5173/</code>.</li><li><code>npm run build</code> — static build → <code>.vitepress/dist/</code>.</li><li><code>npm run preview</code> — preview the production build.</li><li><code>npm run screenshots</code> — Playwright <code>screenshots</code> project (<code>screenshots.spec.ts</code>); drives the live app to capture guide PNGs. Needs <code>SCREENSHOTS_USER</code> / <code>SCREENSHOTS_PASSWORD</code> (and optionally <code>KEYCLOAK_TOKEN_URL</code>, <code>KEYCLOAK_CLIENT_ID</code>); base URL defaults to <code>http://localhost:3000</code> (override with <code>SCREENSHOT_URL</code>).</li><li><code>npm run tour:auth</code> — runs the <code>tour-auth</code> project (<code>tour-auth.setup.ts</code>, <code>--headed</code>): opens a real Chromium, you sign in by hand, and the context is saved to <code>.auth/tour-storage-state.json</code>.</li><li><code>npm run tour</code> — runs the <code>tour</code> project (<code>tour.spec.ts</code>); records the marketing <code>.webm</code>. Reuses the <code>tour:auth</code> storage state; base URL defaults to <code>https://qa.mossworks.io</code> (override with <code>PLAYWRIGHT_BASE_URL</code>).</li><li><code>npm run tour:headed</code> — same as <code>tour</code> but headed.</li></ul><p>There is <strong>no Vitest or unit-test setup</strong> here — Playwright is the only test tooling, and it is for capture, not assertions. <code>take-screenshots.sh</code> is the operator wrapper that orchestrates the full screenshot run.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><code>.vitepress/config.mts</code> — title, nav, sidebar, theme. <code>appearance: &#39;dark&#39;</code>, local search, <code>ignoreDeadLinks: [/localhost/]</code> (so dev/localhost links don&#39;t fail the build).</li><li><code>.vitepress/theme/</code> — custom theme with a screenshot authoring API beyond stock VitePress: <ul><li><code>SchemeImage.vue</code> — <code>&lt;SchemeImage name=&quot;x&quot; /&gt;</code> resolves to <code>/screenshots/x-&lt;scheme&gt;.png</code>, rotating with the active colour scheme.</li><li><code>FlatImage.vue</code> — <code>&lt;FlatImage name=&quot;x&quot; /&gt;</code> resolves to <code>/screenshots/x.png</code> (single-image surfaces).</li><li>Plus <code>HeroCarousel.vue</code>, <code>SchemePickerRaw.vue</code>, <code>index.ts</code> (registers the components), and <code>custom.css</code>.</li></ul></li><li><code>guide/*.md</code> — one page per topic (episodes, proposals, scripts, storyboard, audio, channels, settings, marketplace, agents, jobs, etc.).</li><li><code>public/screenshots/</code> — the PNGs, named <code>&lt;name&gt;-&lt;scheme&gt;.png</code> (7 per scheme-rotated image) or <code>&lt;name&gt;.png</code> (flat). <code>public/CNAME</code> pins the custom domain.</li><li><strong>Capture subsystem (repo root):</strong> <code>playwright.config.ts</code> (defines the three projects: <code>screenshots</code>, <code>tour</code>, <code>tour-auth</code>), <code>screenshots.spec.ts</code>, <code>tour.spec.ts</code>, <code>tour-auth.setup.ts</code>, <code>screenshot-auth.ts</code>, <code>globalSetup.ts</code> (mints the Keycloak ROPC token for <code>screenshots</code>; no-op when <code>SCREENSHOTS_USER</code> is unset so <code>tour</code> can run without those creds), <code>take-screenshots.sh</code>, and <code>seed/</code> (demo-channel fixture data: ideas + scripts).</li></ul><h2 id="key-conventions" tabindex="-1">Key Conventions <a class="header-anchor" href="#key-conventions" aria-label="Permalink to &quot;Key Conventions&quot;">​</a></h2><ul><li><strong>Deploy is push-to-<code>main</code></strong> via <code>.github/workflows/docs.yml</code> (workflow name &quot;Docs&quot;): <code>npm ci &amp;&amp; npm run build</code>, then <code>peaceiris/actions-gh-pages@v4</code> publishes <code>.vitepress/dist</code>. The deploy step is gated <code>if: github.event_name == &#39;push&#39;</code>, so <strong>PRs build but do not deploy</strong>.</li><li><strong>Node 22</strong> in CI (<code>actions/setup-node</code> with <code>node-version: 22</code>).</li><li><strong>Use <code>&lt;SchemeImage&gt;</code> / <code>&lt;FlatImage&gt;</code></strong> for screenshots in guide pages, not raw Markdown image syntax — that is what makes theme/scheme rotation work. New screenshots go into <code>public/screenshots/</code> referenced by <code>name</code>.</li><li><code>package.json</code> pins <code>overrides.esbuild: ^0.25.0</code> (transitive pin); keep it when bumping VitePress/Playwright.</li><li>The two capture workloads share one <code>playwright.config.ts</code> but pin their own <code>use</code> blocks — don&#39;t let <code>devices[&#39;Desktop Chrome&#39;]</code> defaults (it ships a 1280×720 viewport) clobber the per-project viewport; re-pin viewport <strong>after</strong> the device spread.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>There are no unit tests. Verify changes by:</p><ul><li><code>npm run build</code> (what CI runs; catches dead links not matching the <code>/localhost/</code> allowlist and config errors).</li><li><code>npm run dev</code> + visual check of affected <code>guide/*.md</code> pages.</li><li>Regenerating screenshots via <code>npm run screenshots</code> / <code>take-screenshots.sh</code> only when a documented UI surface changed (requires the full app stack + Keycloak creds).</li></ul><h2 id="related-repos" tabindex="-1">Related Repos <a class="header-anchor" href="#related-repos" aria-label="Permalink to &quot;Related Repos&quot;">​</a></h2><ul><li><code>craft-studio/</code>, <code>marketplace/</code> — the frontends this guide documents (and which <code>screenshots</code> / <code>tour</code> drive live).</li><li><code>smoketests/</code> — the workspace&#39;s full-stack E2E harness. This repo&#39;s Playwright subsystem is <strong>doc-specific capture</strong>, separate from the smoketests suite.</li><li><code>helm-charts/</code> (<code>docs</code> chart) and <code>platform-deploy</code> — deploy plumbing for the wider stack; this repo deploys to GitHub Pages on its own.</li></ul><blockquote><p>Workspace note: this repo lives in the Mossworks multi-repo workspace described in the root <code>CLAUDE.md</code>. Stay inside this repo per commit; cross-repo changes need a PR per affected repo.</p></blockquote>',22)])])}const m=o(d,[["render",r]]);export{p as __pageData,m as default};
